import{_ as t,b as l,c as o,g as a}from"./chunks/framework.86O3EbG5.js";const g=JSON.parse('{"title":"概率编程","description":"","frontmatter":{"title":"概率编程","subTitle":"《人工智能现代方法》读书笔记","author":"oasis","date":"2023-04-04T00:00:00.000Z","tags":["AI"]},"headers":[],"relativePath":"articles/ai/books/ai-modern-approach/15.md","filePath":"articles/ai/books/ai-modern-approach/15.md"}'),r={name:"articles/ai/books/ai-modern-approach/15.md"};function e(s,i,n,d,_,p){return l(),o("div",null,[...i[0]||(i[0]=[a('<p>第 15 章关注随时间变化的不确定性系统，核心是如何在序列观测中推断隐藏状态。重点包括：</p><h2 id="动态贝叶斯网络-dbn" tabindex="-1">动态贝叶斯网络（DBN）</h2><ul><li>将贝叶斯网络扩展到时间序列，通常用马尔可夫假设：当前状态只依赖前一时刻状态（一阶马尔可夫）</li><li><strong>转移模型</strong>：P(Xₜ | Xₜ₋₁)，<strong>观测模型</strong>：P(Eₜ | Xₜ)</li><li><strong>联合分布分解</strong>：P(X₀:ₜ, E₁:ₜ) = P(X₀) ∏ₜ₌₁ᵀ P(Xₜ | Xₜ₋₁) P(Eₜ | Xₜ)</li></ul><h2 id="隐马尔可夫模型-hmm" tabindex="-1">隐马尔可夫模型（HMM）</h2><ul><li>状态变量离散、观测变量离散（或连续）</li><li><strong>推理任务</strong>：滤波（当前状态）、预测（未来状态）、平滑（过去状态）、最可能状态序列（维特比算法）</li></ul><h2 id="卡尔曼滤波-kf" tabindex="-1">卡尔曼滤波（KF）</h2><ul><li>状态和观测为连续、服从高斯分布，转移和观测为线性高斯模型</li><li>通过均值和协方差进行解析更新，是最优的线性滤波</li></ul><h2 id="扩展卡尔曼滤波-ekf" tabindex="-1">扩展卡尔曼滤波（EKF）</h2><ul><li>将非线性系统做线性化近似（泰勒展开）</li></ul><h2 id="粒子滤波-pf" tabindex="-1">粒子滤波（PF）</h2><ul><li>适用于非线性、非高斯系统，使用加权粒子集合表示后验分布</li><li><strong>重要步骤</strong>：采样、权重更新、重采样</li></ul><h2 id="推理算法" tabindex="-1">推理算法</h2><ul><li><strong>滤波</strong>：前向算法（HMM）或卡尔曼递推</li><li><strong>平滑</strong>：前向后向算法（HMM）或 RTS 平滑（卡尔曼）</li><li><strong>维特比</strong>：动态规划求最可能路径</li></ul>',13)])])}const h=t(r,[["render",e]]);export{g as __pageData,h as default};
